    while lines and lines[-1].strip() == "":
        lines.pop()
    if not lines:
        return False
    head = lines[0].split()
    if len(head) != 2:
        return False
    try:
        n, q = int(head[0]), int(head[1])
    except ValueError:
        return False
    if not (2 <= n <= 10**6 and 1 <= q <= 2 * 10**5):
        return False
