        return False
    for line in lines[1:]:
        t = line.split()
        if len(t) != 2:
            return False
        if t[0] == "1":
            if t[1] not in ("R", "L", "U", "D"):
                return False
        elif t[0] == "2":
            try:
                p = int(t[1])
            except ValueError:
                return False
            if not (1 <= p <= n):
                return False
        else:
            return False
